import { languageSelector } from "~/renderer/reducers/settings";

const WWW_LEDGER_DOMAIN = "www.ledger.com";
const SUPPORT_LEDGER_DOMAIN = "support.ledger.com";
const SHOP_LEDGER_DOMAIN = "shop.ledger.com";

/**
 * Locale mappings for the www.ledger.com marketing website.
 * Locales not present in the map are inserted as-is (e.g. "fr", "ja").
 */
const wwwLocaleMap: Record<string, string> = {
  pt: "pt-br",
  zh: "zh-hans",
};

/**
 * Locale mappings for the support.ledger.com help center.
 * Locales not present in the map are inserted as-is.
 */
const supportLocaleMap: Record<string, string> = {
  fr: "fr-fr",
  en: "en-us",
  zh: "zh-cn",
};

/**
 * Locale mappings for the shop.ledger.com store.
 * Locales not present in the map are inserted as-is (e.g. "fr", "es").
 */
const shopLocaleMap: Record<string, string> = {
  pt: "pt-br",
};

/**
 * Localizes a URL for the supported Ledger web properties.
 *
 * @param url the URL to localize.
 * @param locale the active locale/language code (e.g. "fr", "en", "pt").
 * @returns the localized URL, or the original URL for unsupported domains.
 */
export function localizeUrl(url: string, locale: string): string {
  let parsed: URL;
  try {
    parsed = new URL(url);
  } catch {
    return url;
  }

  switch (parsed.hostname) {
    case WWW_LEDGER_DOMAIN: {
      const localeCode = wwwLocaleMap[locale] ?? locale;
      parsed.pathname = `/${localeCode}${parsed.pathname}`;
      return parsed.toString();
    }
    case SHOP_LEDGER_DOMAIN: {
      const localeCode = shopLocaleMap[locale] ?? locale;
      parsed.pathname = `/${localeCode}${parsed.pathname}`;
      return parsed.toString();
    }
    case SUPPORT_LEDGER_DOMAIN: {
      if (!parsed.pathname.startsWith("/hc/")) return url;
      const localeCode = supportLocaleMap[locale] ?? locale;
      const rest = parsed.pathname.slice("/hc/".length);
      parsed.pathname = `/hc/${localeCode}/${rest}`;
      return parsed.toString();
    }
    default:
      return url;
  }
}

/**
 * React hook that localizes a URL for Ledger's web properties based on the
 * user's current language setting in the app.
 *
 * @param url the URL to localize.
 * @returns the localized URL, or the original URL for unsupported domains.
 */
export function useLocalizedUrl(url: string): string {
  const locale = useSelector(languageSelector);
  return localizeUrl(url, locale);
}

export default useLocalizedUrl;
